using System.Security.Cryptography;

if (!MLKem.IsSupported)
    throw new PlatformNotSupportedException(
        "ML-KEM needs OpenSSL 3.5+ or Windows 11 / Server 2025 with PQC.");

MLKemAlgorithm alg = MLKemAlgorithm.MLKem768;   // NIST level 3 / CNSA 2.0

// Recipient: generate a keypair, publish only the encapsulation (public) key.
using MLKem recipient = MLKem.GenerateKey(alg);
byte[] encapsulationKey = recipient.ExportEncapsulationKey();

// Sender: encapsulate against the recipient's public key.
using MLKem senderView = MLKem.ImportEncapsulationKey(alg, encapsulationKey);
senderView.Encapsulate(out byte[] ciphertext, out byte[] sharedSecretSender);

// Recipient: decapsulate to recover the identical shared secret.
byte[] sharedSecretRecipient = recipient.Decapsulate(ciphertext);

// The KEM only transports a secret. Don't use it as a key directly: derive a key with a
// KDF, then encrypt with an AEAD. Full envelope on the sender side:
byte[] dataKey = HKDF.DeriveKey(HashAlgorithmName.SHA384, sharedSecretSender,
    outputLength: 32, info: "app: data-key v1"u8.ToArray());
byte[] nonce = RandomNumberGenerator.GetBytes(AesGcm.NonceByteSizes.MaxSize);
byte[] payload = System.Text.Encoding.UTF8.GetBytes("secret message");
byte[] cipher = new byte[payload.Length];
byte[] tag = new byte[AesGcm.TagByteSizes.MaxSize];
using (var gcm = new AesGcm(dataKey, tag.Length))
    gcm.Encrypt(nonce, payload, cipher, tag);
// Send { ciphertext (KEM), nonce, cipher, tag } to the recipient, who derives the same
// dataKey from sharedSecretRecipient and AES-GCM-decrypts.

// Concatenate both shared secrets, then derive the working key from the pair.
// classicalSecret = X25519 ECDH output;  pqcSecret = ML-KEM Decapsulate output.
byte[] combined = [.. classicalSecret, .. pqcSecret];
byte[] key = HKDF.DeriveKey(
    HashAlgorithmName.SHA384, combined,
    outputLength: 32, info: "app: hybrid-kem v1"u8.ToArray());

using System.Security.Cryptography;

if (!MLDsa.IsSupported)
    throw new PlatformNotSupportedException(
        "ML-DSA needs OpenSSL 3.5+ or Windows 11 / Server 2025 with PQC.");

MLDsaAlgorithm alg = MLDsaAlgorithm.MLDsa65;   // NIST level 3 / CNSA 2.0

// Signer
using MLDsa signer = MLDsa.GenerateKey(alg);
byte[] signature = new byte[alg.SignatureSizeInBytes];
signer.SignData(data, signature);

// Publish the public key for verifiers.
byte[] publicKey = new byte[alg.PublicKeySizeInBytes];
signer.ExportMLDsaPublicKey(publicKey);

// Verifier (reconstruct from the published public key)
using MLDsa verifier = MLDsa.ImportMLDsaPublicKey(alg, publicKey);
bool ok = verifier.VerifyData(data, signature);

// Same shape as MLDsa: SlhDsa.GenerateKey(SlhDsaAlgorithm.SlhDsaSha2_128s),
// then SignData / VerifyData. Pick a parameter set deliberately: the 's'
// variants are small-signature/slow, the 'f' variants are fast/large.
